/* BERTH.A RC236 — normalização visual + Biblioteca sincronizada, sem reescrever cards */
(function(){
'use strict';
const BUILD='RC236', PALS=['nevoa','coral','misto'], PREFIX='bertha.kids.accessory.variant.';
const IDS={"rabbit":{"mist_mist_v1_rabbit_head_0":"head","mist_mist_v1_rabbit_neck_1":"neck","mist_mist_v1_rabbit_eyes_2":"eyes","mist_mist_v1_rabbit_back_3":"back","mist_mist_v1_rabbit_special_4":"special"},"owl":{"mist_mist_v1_owl_head_0":"head","mist_mist_v1_owl_neck_1":"neck","mist_mist_v1_owl_eyes_2":"eyes","mist_mist_v1_owl_back_3":"back","mist_mist_v1_owl_special_4":"special"},"deer":{"mist_mist_v1_deer_head_0":"head","mist_mist_v1_deer_neck_1":"neck","mist_mist_v1_deer_eyes_2":"eyes","mist_mist_v1_deer_back_3":"back","mist_mist_v1_deer_special_4":"special"},"bear":{"mist_mist_v1_bear_head_0":"head","mist_mist_v1_bear_neck_1":"neck","mist_mist_v1_bear_eyes_2":"eyes","mist_mist_v1_bear_back_3":"back","mist_mist_v1_bear_special_4":"special"}};
const NAMES={"mist_mist_v1_rabbit_head_0":"Boné de Nuvem","mist_mist_v1_rabbit_neck_1":"Bandana de Bruma","mist_mist_v1_rabbit_eyes_2":"Óculos de Grau Nuvem","mist_mist_v1_rabbit_back_3":"Mochila Saltinho","mist_mist_v1_rabbit_special_4":"Pingente Coelho de Nuvem","mist_mist_v1_owl_head_0":"Chapéu Pena Lunar","mist_mist_v1_owl_neck_1":"Gravata Lua-Sábia","mist_mist_v1_owl_eyes_2":"Óculos de Leitura Lunar","mist_mist_v1_owl_back_3":"Bolsa Livro Celeste","mist_mist_v1_owl_special_4":"Amuleto de Pena","mist_mist_v1_deer_head_0":"Tiara Nuvem Lunar","mist_mist_v1_deer_neck_1":"Coleira Celeste","mist_mist_v1_deer_eyes_2":"Monóculo de Trilha","mist_mist_v1_deer_back_3":"Alforge Nuvem","mist_mist_v1_deer_special_4":"Varinha Mágica Lunar","mist_mist_v1_bear_head_0":"Gorro Soninho de Bruma","mist_mist_v1_bear_neck_1":"Lenço de Bruma","mist_mist_v1_bear_eyes_2":"Óculos Redondos","mist_mist_v1_bear_back_3":"Mochila de Bruma","mist_mist_v1_bear_special_4":"Pingente Sonho de Bruma"};
const ASSETS={"rabbit-head-nevoa":"data:image/png;base64,","rabbit-head-coral":"data:image/png;base64,","rabbit-head-misto":"data:image/png;base64,","rabbit-neck-nevoa":"data:image/png;base64,","rabbit-neck-coral":"data:image/png;base64,","rabbit-neck-misto":"data:image/png;base64,","rabbit-eyes-nevoa":"data:image/png;base64,","rabbit-eyes-coral":"data:image/png;base64,","rabbit-eyes-misto":"data:image/png;base64,","rabbit-back-nevoa":"data:image/png;base64,","rabbit-back-coral":"data:image/png;base64,","rabbit-back-misto":"data:image/png;base64,","rabbit-special-nevoa":"data:image/png;base64,","rabbit-special-coral":"data:image/png;base64,","rabbit-special-misto":"data:image/png;base64,","owl-head-nevoa":"data:image/png;base64,","owl-head-coral":"data:image/png;base64,","owl-head-misto":"data:image/png;base64,","owl-neck-nevoa":"data:image/png;base64,","owl-neck-coral":"data:image/png;base64,","owl-neck-misto":"data:image/png;base64,","owl-eyes-nevoa":"data:image/png;base64,","owl-eyes-coral":"data:image/png;base64,","owl-eyes-misto":"data:image/png;base64,","owl-back-nevoa":"data:image/png;base64,","owl-back-coral":"data:image/png;base64,","owl-back-misto":"data:image/png;base64,","owl-special-nevoa":"data:image/png;base64,","owl-special-coral":"data:image/png;base64,","owl-special-misto":"data:image/png;base64,","deer-head-nevoa":"data:image/png;base64,","deer-head-coral":"data:image/png;base64,","deer-head-misto":"data:image/png;base64,","deer-neck-nevoa":"data:image/png;base64,","deer-neck-coral":"data:image/png;base64,","deer-neck-misto":"data:image/png;base64,","deer-eyes-nevoa":"data:image/png;base64,","deer-eyes-coral":"data:image/png;base64,","deer-eyes-misto":"data:image/png;base64,","deer-back-nevoa":"data:image/png;base64,","deer-back-coral":"data:image/png;base64,","deer-back-misto":"data:image/png;base64,","deer-special-nevoa":"data:image/png;base64,","deer-special-coral":"data:image/png;base64,","deer-special-misto":"data:image/png;base64,","bear-head-nevoa":"data:image/png;base64,","bear-head-coral":"data:image/png;base64,","bear-head-misto":"data:image/png;base64,","bear-neck-nevoa":"data:image/png;base64,","bear-neck-coral":"data:image/png;base64,","bear-neck-misto":"data:image/png;base64,","bear-eyes-nevoa":"data:image/png;base64,","bear-eyes-coral":"data:image/png;base64,","bear-eyes-misto":"data:image/png;base64,","bear-back-nevoa":"data:image/png;base64,","bear-back-coral":"data:image/png;base64,","bear-back-misto":"data:image/png;base64,","bear-special-nevoa":"data:image/png;base64,","bear-special-coral":"data:image/png;base64,","bear-special-misto":"data:image/png;base64,"};

const store=()=>window.berthaHmlStorage||window.localStorage;
function selectedKid(){const s=document.querySelector('#r152KidSel');if(s&&s.value)return String(s.value);if(window.__rc209Member!=null)return String(window.__rc209Member);return String(store().getItem('bertha.rewards.selected.kid')||'default');}
function variantFor(aid){const n=Number(store().getItem(PREFIX+selectedKid()+'.'+aid));return Number.isFinite(n)?Math.max(0,Math.min(2,n)):2;}
function locate(aid){for(const animal of Object.keys(IDS)){const kind=IDS[animal][aid];if(kind)return {animal,kind};}return null;}
function patchKit(){
  document.querySelectorAll('.rc209-acc-proxy[data-acc]').forEach(proxy=>{
    const aid=proxy.getAttribute('data-acc'), hit=locate(aid); if(!hit)return;
    const src=ASSETS[hit.animal+'-'+hit.kind+'-'+PALS[variantFor(aid)]]; if(!src)return;
    proxy.classList.add('rc236-normalized','rc236-'+hit.animal); proxy.dataset.rc236='1';
    let im=proxy.querySelector('img'); if(!im){proxy.replaceChildren();im=document.createElement('img');im.alt='';im.loading='eager';im.decoding='async';proxy.appendChild(im);}
    if(im.getAttribute('src')!==src) im.setAttribute('src',src);
    const card=proxy.closest('.r197-acc'); if(card){const title=card.querySelector('strong'); if(title&&NAMES[aid])title.textContent=NAMES[aid];}
  });
}
function patchLibrary(){
  document.querySelectorAll('.rc208-library').forEach(lib=>{
    const section=lib.closest('.r197-card'); if(!section)return;
    const petName=(section.querySelector('h3')?.textContent||'').trim();
    // The KIT card is the nearest earlier card with five accessory proxies.
    let kit=section.previousElementSibling;
    while(kit && !kit.querySelector('.r197-acc-grid')) kit=kit.previousElementSibling;
    if(!kit)return;
    const cards=[...kit.querySelectorAll('.r197-acc')];
    const slots=[...lib.children]; if(!cards.length||!slots.length)return;
    slots.slice(0,5).forEach((slot,i)=>{
      const card=cards[i]; if(!card)return;
      const src=card.querySelector('.rc209-acc-proxy img')?.getAttribute('src');
      const label=(card.querySelector('strong')?.textContent||'').trim();
      const box=slot.querySelector('i'); const text=slot.querySelector('b');
      if(box&&src){ let im=box.querySelector('img'); if(!im){box.replaceChildren();im=document.createElement('img');im.alt='';im.loading='eager';im.decoding='async';box.appendChild(im);} if(im.getAttribute('src')!==src)im.setAttribute('src',src); }
      if(text&&label) text.textContent=label;
      slot.dataset.rc236Library='1';
    });
    lib.dataset.rc236Synced='1';
  });
}
function stamp(){
 document.documentElement.dataset.berthaBuild=BUILD;document.documentElement.dataset.berthaIndex=BUILD;document.title='BERTH.A · Homologação '+BUILD;
 const idx=document.getElementById('rc157IndexBadge');if(idx)idx.textContent='INDEX · '+BUILD;
 document.querySelectorAll('body *').forEach(el=>{if(el.children.length)return;const t=(el.textContent||'').trim();if(/^HML\s*·\s*RC\d+/i.test(t))el.textContent='HML · '+BUILD;});
}
const style=document.createElement('style'); style.id='rc236-normalize-library-style'; style.textContent=`
.r197-acc:has(.rc236-normalized) .r197-acc-art{height:186px!important;min-height:186px!important;overflow:visible!important;display:flex!important;align-items:center!important;justify-content:center!important}
.r197-acc-art .rc236-normalized{width:100%!important;height:100%!important;display:flex!important;align-items:center!important;justify-content:center!important;overflow:visible!important;background:transparent!important}
.r197-acc-art .rc236-normalized img{display:block!important;width:auto!important;height:176px!important;max-width:97%!important;max-height:176px!important;object-fit:contain!important;object-position:center!important;transform:none!important;filter:saturate(1.10) contrast(1.07) brightness(.97)!important}
.rc208-library i{overflow:hidden!important;display:flex!important;align-items:center!important;justify-content:center!important}
.rc208-library i img{display:block!important;width:94%!important;height:94%!important;object-fit:contain!important;object-position:center!important;filter:saturate(1.08) contrast(1.05) brightness(.98)!important}
.rc208-library [data-rc236-library="1"] b{font-weight:500!important}
`; document.head.appendChild(style);
function patch(){patchKit();requestAnimationFrame(()=>patchLibrary());stamp();}
let raf=0;function schedule(){if(raf)return;raf=requestAnimationFrame(()=>{raf=0;patch();});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',schedule,{once:true});else schedule();
window.addEventListener('pageshow',schedule);window.addEventListener('hashchange',()=>setTimeout(schedule,40));
document.addEventListener('click',e=>{if(e.target.closest('[data-r147tab="kids"],[data-rc209variant],[data-r152pet],#rc208PetSel,#r152KidSel'))setTimeout(schedule,60);},true);
document.addEventListener('change',e=>{if(e.target.matches('#rc208PetSel,#r152KidSel'))setTimeout(schedule,60);},true);
[100,260,600,1200,2200].forEach(ms=>setTimeout(schedule,ms));
})();
